1	import { runScenario, type Scenario } from "./claim-office.js";
2	
3	const readStdin = async (): Promise<string> => {
4	  const chunks: Buffer[] = [];
5	
6	  for await (const chunk of process.stdin) {
7	    chunks.push(chunk as Buffer);
8	  }
9	
10	  return Buffer.concat(chunks).toString("utf8");
11	};
12	
13	const describe = (error: unknown): string =>
14	  error instanceof Error ? error.message : String(error);
15	
16	// The scenario is computed in full before anything is written, so a rejected
17	// scenario leaves stdout empty rather than half-written.
18	const main = async (): Promise<void> => {
19	  const scenario = JSON.parse(await readStdin()) as Scenario;
20	
21	  process.stdout.write(JSON.stringify(runScenario(scenario)));
22	};
23	
24	main().catch((error: unknown) => {
25	  process.stderr.write(`${describe(error)}\n`);
26	  process.exitCode = 1;
27	});
