1	export type Item = {
2	  type: string;
3	  material?: string;
4	  enchantment?: number;
5	  cursed?: boolean;
6	};
7	
8	export type Damage = {
9	  itemType: string;
10	  amount: number;
11	};
12	
13	export type Incident = {
14	  cause: string;
15	  damages: Damage[];
16	};
17	
18	export type Step = {
19	  op: string;
20	  items?: Item[];
21	  policy?: number;
22	  incident?: Incident;
23	};
24	
25	export type Customer = {
26	  yearsWithMHPCO: number;
27	};
28	
29	export type Scenario = {
30	  customer: Customer;
31	  steps: Step[];
32	};
33	
34	export type QuoteResult = {
35	  premium: number;
36	};
37	
38	export type ClaimResult = {
39	  payout: number;
40	  remainingCap: number;
41	};
42	
43	// A scenario's results are heterogeneous: a quote step yields a premium, a
44	// claim step a payout and the cap left on its policy.
45	export type StepResult = QuoteResult | ClaimResult;
46	
47	export type ScenarioResults = {
48	  results: StepResult[];
49	};
50	
51	// --- Quotes ------------------------------------------------------------------
52	
53	const PROCESSING_FEE = 5;
54	
55	const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
56	  sword: 100,
57	  amulet: 60,
58	  staff: 80,
59	  potion: 40,
60	  rune: 25,
61	  moonstone: 25,
62	};
63	
64	// Charged on every quote, unconditionally — it is the cost of assessing the
65	// items, not a penalty for being a new customer. Named "first insurance" in
66	// some of the domain material, which misleads: it does not depend on customer
67	// history or on the quote's position in the scenario.
68	const INITIAL_ASSESSMENT_SURCHARGE_PERCENT = 10;
69	
70	const WHOLE_PERCENT = 100;
71	
72	const percentOf = (amount: number, percent: number): number =>
73	  (amount * percent) / WHOLE_PERCENT;
74	
75	// The tables keyed by item type cover exactly the types the MHPCO insures.
76	// Anything else is not a mispriced item, it is not an item at all, so a lookup
77	// miss is an error rather than a zero. `priceName` names the price the table
78	// holds, so the rejection can say which one the item had none of.
79	const lookUpByItemType = (
80	  table: Record<string, number>,
81	  item: Item,
82	  priceName: string,
83	): number => {
84	  const value = table[item.type];
85	
86	  if (value === undefined) {
87	    throw new Error(`unknown item type "${item.type}": no ${priceName}`);
88	  }
89	
90	  return value;
91	};
92	
93	const itemBasePremium = (item: Item): number =>
94	  lookUpByItemType(BASE_PREMIUM_BY_TYPE, item, "base premium");
95	
96	const BLOCK_SIZE = 3;
97	
98	const BLOCK_PREMIUM = 60;
99	
100	const sumOf = (amounts: number[]): number =>
101	  amounts.reduce((sum, amount) => sum + amount, 0);
102	
103	const formsABlock = (items: Item[]): boolean => items.length === BLOCK_SIZE;
104	
105	const sumOfItemBasePremiums = (items: Item[]): number =>
106	  sumOf(items.map(itemBasePremium));
107	
108	// Grouping by type is the one piece of knowledge shared by the two places that
109	// care about how many of a kind there are: premiums price alike items together,
110	// and a claim compares damaged counts against insured counts. Both take their
111	// key from a type field, so `typeOf` says which field on the element that is.
112	const groupByType = <T>(
113	  elements: T[],
114	  typeOf: (element: T) => string,
115	): Map<string, T[]> => {
116	  const groups = new Map<string, T[]>();
117	
118	  for (const element of elements) {
119	    const type = typeOf(element);
120	    groups.set(type, [...(groups.get(type) ?? []), element]);
121	  }
122	
123	  return groups;
124	};
125	
126	const itemType = (item: Item): string => item.type;
127	
128	// Items of the same type are "alike" and are priced together, so the policy
129	// base premium is computed group by group rather than item by item.
130	const alikeGroups = (items: Item[]): Item[][] => [
131	  ...groupByType(items, itemType).values(),
132	];
133	
134	const alikeGroupBasePremium = (alikeItems: Item[]): number =>
135	  formsABlock(alikeItems)
136	    ? BLOCK_PREMIUM
137	    : sumOfItemBasePremiums(alikeItems);
138	
139	const policyBasePremium = (items: Item[]): number =>
140	  sumOf(alikeGroups(items).map(alikeGroupBasePremium));
141	
142	// One domain rule — "round in the MHPCO's favour" — which cuts in opposite
143	// directions depending on which way the money moves: a premium is collected, so
144	// a fraction rounds up; a payout is paid, so a fraction rounds down. The two are
145	// stated as separate functions rather than one taking a direction, because they
146	// share no computation, only a motive: a single helper would have to reintroduce
147	// the collected/paid distinction as a runtime conditional, and each call site
148	// would name its direction in an argument instead of in the function it calls.
149	// Both are applied to a final amount only; intermediates stay fractional.
150	const roundPremiumInMHPCOsFavor = (amount: number): number =>
151	  Math.ceil(amount);
152	
153	const roundPayoutInMHPCOsFavor = (amount: number): number => Math.floor(amount);
154	
155	// The inputs a single quote is computed from: `items` drives the base premium
156	// and item-scoped surcharges, `customer` and `precedingQuoteCount` drive the
157	// policy-wide modifiers. The count is of preceding QUOTE steps, not of steps in
158	// general — a claim step is not a contract and must not trigger the follow-up
159	// discount.
160	type QuoteRequest = {
161	  customer: Customer;
162	  items: Item[];
163	  precedingQuoteCount: number;
164	};
165	
166	const LOYALTY_YEARS = 2;
167	
168	const LOYALTY_DISCOUNT_PERCENT = 20;
169	
170	// Modifier percents are signed so surcharges and discounts can be summed
171	// uniformly; a discount enters the sum as its negation.
172	const asDiscount = (percent: number): number => -percent;
173	
174	const isLoyal = (customer: Customer): boolean =>
175	  customer.yearsWithMHPCO >= LOYALTY_YEARS;
176	
177	const FOLLOW_UP_CONTRACT_DISCOUNT_PERCENT = 15;
178	
179	const isFollowUpContract = (request: QuoteRequest): boolean =>
180	  request.precedingQuoteCount > 0;
181	
182	const policyModifierPercents = (request: QuoteRequest): number[] => [
183	  INITIAL_ASSESSMENT_SURCHARGE_PERCENT,
184	  ...(isLoyal(request.customer) ? [asDiscount(LOYALTY_DISCOUNT_PERCENT)] : []),
185	  ...(isFollowUpContract(request)
186	    ? [asDiscount(FOLLOW_UP_CONTRACT_DISCOUNT_PERCENT)]
187	    : []),
188	];
189	
190	// Policy-wide modifiers do NOT compound: each is an independent percentage of
191	// the policy base premium, and they are summed. Chaining them (base * 1.1 * 0.8)
192	// would give a different, wrong answer.
193	const applyPolicyModifiers = (
194	  basePremium: number,
195	  request: QuoteRequest,
196	): number =>
197	  basePremium +
198	  sumOf(
199	    policyModifierPercents(request).map((percent) =>
200	      percentOf(basePremium, percent),
201	    ),
202	  );
203	
204	const CURSE_SURCHARGE_PERCENT = 50;
205	
206	const HIGH_ENCHANTMENT_LEVEL = 5;
207	
208	const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
209	
210	const isHighlyEnchanted = (item: Item): boolean =>
211	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL;
212	
213	const isCursed = (item: Item): boolean => item.cursed === true;
214	
215	type ItemSurchargeRule = {
216	  applies: (item: Item) => boolean;
217	  percent: number;
218	};
219	
220	const ITEM_SURCHARGE_RULES: ItemSurchargeRule[] = [
221	  { applies: isCursed, percent: CURSE_SURCHARGE_PERCENT },
222	  { applies: isHighlyEnchanted, percent: HIGH_ENCHANTMENT_SURCHARGE_PERCENT },
223	];
224	
225	// Item-scoped surcharges are charged on the item's own base premium, so they
226	// must NOT go through applyPolicyModifiers.
227	const itemSurcharges = (item: Item): number =>
228	  sumOf(
229	    ITEM_SURCHARGE_RULES.filter((rule) => rule.applies(item)).map((rule) =>
230	      percentOf(itemBasePremium(item), rule.percent),
231	    ),
232	  );
233	
234	const policyItemSurcharges = (items: Item[]): number =>
235	  sumOf(items.map(itemSurcharges));
236	
237	const quotePremium = (request: QuoteRequest): number =>
238	  roundPremiumInMHPCOsFavor(
239	    applyPolicyModifiers(policyBasePremium(request.items), request) +
240	      policyItemSurcharges(request.items) +
241	      PROCESSING_FEE,
242	  );
243	
244	// --- Claims -----------------------------------------------------------------
245	// An item's insurance value is what it is worth if destroyed, and is unrelated
246	// to its premium: the premium is what the customer pays to be covered. The two
247	// tables below happen to agree on a 10x ratio today, but that is a property of
248	// the current price list and not a rule of the domain — repricing premiums must
249	// not silently revalue payouts, so they stay separate.
250	const INSURANCE_VALUE_BY_TYPE: Record<string, number> = {
251	  sword: 1000,
252	  amulet: 600,
253	  staff: 800,
254	  potion: 400,
255	  rune: 250,
256	  moonstone: 250,
257	};
258	
259	const itemInsuranceValue = (item: Item): number =>
260	  lookUpByItemType(INSURANCE_VALUE_BY_TYPE, item, "insurance value");
261	
262	const insuranceSum = (items: Item[]): number =>
263	  sumOf(items.map(itemInsuranceValue));
264	
265	// A policy pays out at most twice what it insures.
266	const CAP_MULTIPLIER = 2;
267	
268	const policyCap = (items: Item[]): number =>
269	  CAP_MULTIPLIER * insuranceSum(items);
270	
271	const DEDUCTIBLE = 100;
272	
273	const HALF_REIMBURSEMENT_ENCHANTMENT_LEVEL = 8;
274	
275	const HALF_REIMBURSEMENT_PERCENT = 50;
276	
277	const isHalfReimbursed = (item: Item): boolean =>
278	  (item.enchantment ?? 0) >= HALF_REIMBURSEMENT_ENCHANTMENT_LEVEL;
279	
280	const DRAGON_MATERIAL = "dragon";
281	
282	const isDragonMaterial = (item: Item): boolean =>
283	  item.material === DRAGON_MATERIAL;
284	
285	// A damage entry names the item it damaged by type. The MHPCO only reimburses
286	// what it insured, so a type the policy does not cover is a rejection rather
287	// than an uncovered-but-tolerated entry.
288	const damagedItem = (insuredItems: Item[], damage: Damage): Item => {
289	  const item = insuredItems.find((insured) => insured.type === damage.itemType);
290	
291	  if (item === undefined) {
292	    throw new Error(
293	      `damaged item "${damage.itemType}" is not covered by this policy`,
294	    );
295	  }
296	
297	  return item;
298	};
299	
300	const FULL_REIMBURSEMENT_PERCENT = 100;
301	
302	// A reimbursement clause pays a stated percentage of the damage. Clauses are
303	// listed in precedence order and the first applicable one wins.
304	type ReimbursementClause = {
305	  applies: (item: Item) => boolean;
306	  percent: number;
307	};
308	
309	const REIMBURSEMENT_CLAUSES: ReimbursementClause[] = [
310	  // Half reimbursement outranks the dragon clause: the spec's "50 % rule wins"
311	  // example is a dragon-material item enchanted to 8, and it pays out half.
312	  { applies: isHalfReimbursed, percent: HALF_REIMBURSEMENT_PERCENT },
313	  // "Damage to items made of dragon material is fully reimbursed." This clause
314	  // is currently indistinguishable from the fallback below — every example it
315	  // matches would reimburse in full anyway, so removing it would not change a
316	  // single result, and no test can tell it is here. It is stated regardless
317	  // because it is a rule the domain asserts about dragon material, not an
318	  // accident of what the other rules happen to leave over. Should a future rule
319	  // ever reduce reimbursement below 100 % for some other reason, dragon items
320	  // must keep their full payout, and this line is what will say so.
321	  { applies: isDragonMaterial, percent: FULL_REIMBURSEMENT_PERCENT },
322	];
323	
324	// An item no clause matches is reimbursed in full: that is the domain's
325	// default, not a fallback for a missing item. `damagedItem` now rejects a
326	// damage naming a type the policy does not cover, so there is no such thing
327	// here as an item that isn't there.
328	const reimbursementPercent = (item: Item): number =>
329	  REIMBURSEMENT_CLAUSES.find((clause) => clause.applies(item))?.percent ??
330	  FULL_REIMBURSEMENT_PERCENT;
331	
332	// A damage is something that happened to an item; a negative one is not a
333	// smaller damage but a nonsensical report, so it is rejected rather than
334	// netted off against the rest of the claim.
335	const damageAmount = (damage: Damage): number => {
336	  if (damage.amount < 0) {
337	    throw new Error(
338	      `damage amount ${damage.amount} for "${damage.itemType}" is negative`,
339	    );
340	  }
341	
342	  return damage.amount;
343	};
344	
345	// What a damage entry reimburses before the deductible: a percentage of the
346	// damage amount, decided by the clauses covering the damaged item.
347	const reimbursableAmount = (insuredItems: Item[], damage: Damage): number =>
348	  percentOf(
349	    damageAmount(damage),
350	    reimbursementPercent(damagedItem(insuredItems, damage)),
351	  );
352	
353	// The deductible applies once per damage event, i.e. per entry in `damages`,
354	// and always last — after the clause has decided the reimbursable amount.
355	const damagePayout = (insuredItems: Item[], damage: Damage): number =>
356	  reimbursableAmount(insuredItems, damage) - DEDUCTIBLE;
357	
358	// --- Running a scenario ------------------------------------------------------
359	
360	const isQuote = (step: Step): boolean => step.op === "quote";
361	
362	// What the scenario has accumulated so far. Steps are folded rather than mapped
363	// because a step's result depends on the steps before it: `precedingQuoteCount`
364	// drives the follow-up discount today, and claim steps will thread a remaining
365	// cap through the same carry.
366	// A policy as it stands at some point in the scenario: what it insures, and how
367	// much of its cap is left. The remaining cap belongs to the policy rather than
368	// to a side table because successive claims spend it down — it is the one part
369	// of a policy that changes over the scenario's lifetime.
370	type Policy = {
371	  insuredItems: Item[];
372	  remainingCap: number;
373	};
374	
375	const issuePolicy = (insuredItems: Item[]): Policy => ({
376	  insuredItems,
377	  remainingCap: policyCap(insuredItems),
378	});
379	
380	type ScenarioState = {
381	  results: StepResult[];
382	  precedingQuoteCount: number;
383	  // Policies issued by earlier quote steps, keyed by that step's index — a
384	  // claim names its policy that way (`step.policy`).
385	  policiesByStep: Map<number, Policy>;
386	};
387	
388	const INITIAL_STATE: ScenarioState = {
389	  results: [],
390	  precedingQuoteCount: 0,
391	  policiesByStep: new Map(),
392	};
393	
394	const withPolicy = (
395	  state: ScenarioState,
396	  stepIndex: number,
397	  policy: Policy,
398	): ScenarioState => ({
399	  ...state,
400	  policiesByStep: new Map(state.policiesByStep).set(stepIndex, policy),
401	});
402	
403	// Running a step is a state transition: it reads the carry accumulated by the
404	// preceding steps and returns the next carry. Every step kind gets its own
405	// runner, so `runStep` below is pure dispatch on `op` — the place a claim runner
406	// will be added without touching the quote path.
407	type StepRunner = (
408	  customer: Customer,
409	  state: ScenarioState,
410	  step: Step,
411	  stepIndex: number,
412	) => ScenarioState;
413	
414	const appendResult = (
415	  state: ScenarioState,
416	  result: StepResult,
417	): ScenarioState => ({ ...state, results: [...state.results, result] });
418	
419	const runQuoteStep: StepRunner = (customer, state, step, stepIndex) => {
420	  const items = step.items ?? [];
421	
422	  const premium = quotePremium({
423	    customer,
424	    items,
425	    precedingQuoteCount: state.precedingQuoteCount,
426	  });
427	
428	  return withPolicy(
429	    {
430	      ...appendResult(state, { premium }),
431	      precedingQuoteCount: state.precedingQuoteCount + 1,
432	    },
433	    stepIndex,
434	    issuePolicy(items),
435	  );
436	};
437	
438	// A claim names its policy by the index of the quote step that issued it. A
439	// claim that names no policy, or names one no quote step issued, is not a claim
440	// for 0 G — there is nothing to claim against, so it is rejected. Resolving
441	// yields the key as well as the policy, so that debiting the cap later needs no
442	// second, separately-justified lookup of `step.policy` — the key travelled with
443	// the thing it addresses.
444	type ClaimedPolicy = { key: number; policy: Policy };
445	
446	const claimedPolicy = (state: ScenarioState, step: Step): ClaimedPolicy => {
447	  const key = step.policy;
448	
449	  if (key === undefined) {
450	    throw new Error("claim names no policy");
451	  }
452	
453	  const policy = state.policiesByStep.get(key);
454	
455	  if (policy === undefined) {
456	    throw new Error(`claim against unknown policy ${key}`);
457	  }
458	
459	  return { key, policy };
460	};
461	
462	const countsByType = <T>(
463	  elements: T[],
464	  typeOf: (element: T) => string,
465	): Map<string, number> =>
466	  new Map(
467	    [...groupByType(elements, typeOf)].map(([type, group]) => [
468	      type,
469	      group.length,
470	    ]),
471	  );
472	
473	const damagedType = (damage: Damage): string => damage.itemType;
474	
475	// Each damage entry is a separate damaged item, so a policy insuring one sword
476	// cannot suffer two sword damages. Over-claiming rejects the whole claim rather
477	// than the offending entry — the MHPCO does not part-settle a suspect report.
478	const rejectOverClaiming = (insuredItems: Item[], damages: Damage[]): void => {
479	  const insuredCounts = countsByType(insuredItems, itemType);
480	
481	  for (const [type, claimed] of countsByType(damages, damagedType)) {
482	    const insured = insuredCounts.get(type) ?? 0;
483	
484	    if (claimed > insured) {
485	      throw new Error(
486	        `claim reports ${claimed} damaged "${type}" but the policy covers ${insured}`,
487	      );
488	    }
489	  }
490	};
491	
492	const runClaimStep: StepRunner = (_customer, state, step) => {
493	  const damages = step.incident?.damages ?? [];
494	  const { key, policy } = claimedPolicy(state, step);
495	  const { insuredItems, remainingCap } = policy;
496	
497	  rejectOverClaiming(insuredItems, damages);
498	
499	  // The clamp is outside the per-damage sum: the whole claim is limited by
500	  // what is left of the policy's cap, not each damage individually. The sum is
501	  // rounded before the cap is spent down, so the cap stays whole too.
502	  const desiredPayout = roundPayoutInMHPCOsFavor(
503	    sumOf(damages.map((damage) => damagePayout(insuredItems, damage))),
504	  );
505	  const payout = Math.min(desiredPayout, remainingCap);
506	  const capAfterClaim = remainingCap - payout;
507	
508	  return withPolicy(
509	    appendResult(state, { payout, remainingCap: capAfterClaim }),
510	    key,
511	    { ...policy, remainingCap: capAfterClaim },
512	  );
513	};
514	
515	const runStep: StepRunner = (customer, state, step, stepIndex) =>
516	  isQuote(step)
517	    ? runQuoteStep(customer, state, step, stepIndex)
518	    : runClaimStep(customer, state, step, stepIndex);
519	
520	// The customer is scenario-wide, so it is closed over rather than threaded
521	// through the fold alongside the per-step state.
522	const stepRunnerFor =
523	  (customer: Customer) =>
524	  (state: ScenarioState, step: Step, stepIndex: number) =>
525	    runStep(customer, state, step, stepIndex);
526	
527	export const runScenario = (scenario: Scenario): ScenarioResults => ({
528	  results: scenario.steps.reduce(stepRunnerFor(scenario.customer), INITIAL_STATE)
529	    .results,
530	});
